import itertools

def get_divisors(n):
    if n == 0:
        return []
    divs = []
    for i in range(1, int(abs(n)**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            divs.append(-i)
            divs.append(n // i)
            divs.append(-(n // i))
    return list(set(divs))

def find_good_functions(n, range_limit=4):
    S = list(range(-range_limit, range_limit + 1))
    candidates = {}
    for a in S:
        if a == 1:
            candidates[a] = [1]
        else:
            val = a**n - 1
            if val == 0:
                # This only happens if a=1 (handled) or (n even and a=-1).
                # We are only testing odd n here.
                candidates[a] = [1] # Dummy, though this part shouldn't be reached for odd n
            else:
                candidates[a] = [1 + d for d in get_divisors(val)]

    S_keys = list(candidates.keys())
    S_keys.remove(1)

    results = []
    def backtrack(idx, current_g):
        if idx == len(S_keys):
            results.append(current_g.copy())
            return

        a = S_keys[idx]
        for val in candidates[a]:
            possible = True
            for b, g_b in current_g.items():
                diff_g = val - g_b
                diff_pow = a**n - b**n
                if diff_g == 0:
                    if diff_pow != 0:
                        possible = False
                        break
                else:
                    if diff_pow % diff_g != 0:
                        possible = False
                        break
            if possible:
                current_g[a] = val
                backtrack(idx + 1, current_g)
                del current_g[a]

    backtrack(0, {1: 1})
    return results

for n in [1, 3, 5, 7, 9, 11, 13, 15]:
    res = find_good_functions(n)
    print(f"n={n}, N(n)={len(res)}")

def find_good_functions_full(n, range_limit=2):
    S = list(range(-range_limit, range_limit + 1))
    results = []
    def backtrack(idx, current_g):
        if idx == len(S):
            results.append(current_g.copy())
            return
        a = S[idx]
        if a == 1:
            backtrack(idx + 1, {**current_g, 1: 1})
            return
        b_fixed = None
        for b in current_g:
            if a**n - b**n != 0:
                b_fixed = b
                break
        if b_fixed is None:
            # Try a reasonable range
            for val in range(-5, 6):
                possible = True
                for b, g_b in current_g.items():
                    diff_g = val - g_b
                    diff_pow = a**n - b**n
                    if diff_g == 0:
                        if diff_pow != 0:
                            possible = False
                            break
                    else:
                        if diff_pow % diff_g != 0:
                            possible = False
                            break
                if possible:
                    current_g[a] = val
                    backtrack(idx + 1, current_g)
                    del current_g[a]
        else:
            divs = get_divisors(a**n - b_fixed**n)
            for d in divs:
                val = d + current_g[b_fixed]
                possible = True
                for b, g_b in current_g.items():
                    diff_g = val - g_b
                    diff_pow = a**n - b**n
                    if diff_g == 0:
                        if diff_pow != 0:
                            possible = False
                            break
                    else:
                        if diff_pow % diff_g != 0:
                            possible = False
                            break
                if possible:
                    current_g[a] = val
                    backtrack(idx + 1, current_g)
                    del current_g[a]
    backtrack(0, {})
    return results

# I'll use a very small range and see what the functions look like for n=2.
res2 = find_good_functions_full(2, 1)
